import json
n=30
g=[[0]*n for _ in range(n)]
for c in range(1,26):
    g[1][c]=g[25][c]=5
for r in range(1,26):
    g[r][1]=g[r][25]=5
# Fill successive one-cell inset frames, alternating 2 and 5; leave final 3x3 blank.
for depth, color in enumerate([2,5]*5):
    lo=2+depth; hi=24-depth
    for c in range(lo,hi+1):
        g[lo][c]=g[hi][c]=color
    for r in range(lo,hi+1):
        g[r][lo]=g[r][hi]=color
assert len(g)==30 and all(len(row)==30 for row in g)
print(json.dumps({'action':'submit','grid':g}))
